    reject(lambda:h4abs_marker(''))
    marker='H4ABS_ACTIVE_GO: ND-SSTR-ABS-V1 '+str(H4ABS_OUTPUT)+' '+'a'*64+' '+'b'*64+' m463_runs/m470_h4abs_full_static_fixture.log '+'c'*64
