        i=next(i for i,e in enumerate(ev) if e[0]=='attempt')
        write(ev[:i+1]);rp.write_bytes(b'')
        got=h4absd_read(p,mock)
        h4abs_req(got['attempted']==1 and got['recorded']==0 and got['pending']==[0,0,-1,1],'ABSD partial pending')
