def h4r12_dev_marker(rules):
    import re
    lines=[x for x in rules.splitlines() if re.match(r'^[A-Z0-9_]+_GO:',x)]
    h4m12_req(len(lines)==1,'HOLD_OR_CONFLICT')
    m=re.fullmatch(r'H4R12_EVAL_ACTIVE_GO: H4-M17-R12-DEV-V1 m463_runs/m470_h4_m17_1_r12_dev_v1/report.json '
        r'([0-9a-f]{64}) ([0-9a-f]{64}) (m463_runs/m470_h4r12_dev_static_[A-Za-z0-9_]+\.log) ([0-9a-f]{64})',lines[0])
    h4m12_req(m is not None,'R12_MARKER')
    source,provenance,log,digest=m.groups()
    return dict(id=H4R12_DEV_SPEC['id'],output=str(H4R12_DEV_OUTPUT),source_sha256=source,
        provenance_sha256=provenance,static_path=log,static_sha256=digest)

def h4r12_dev_projection(raw):
    if b'# H4FFE_DEV_'+b'BEGIN\n' in raw:raw=h4ffe_dev_projection(raw)
    begin=b'# H4R12_DEV_'+b'BEGIN\n';end=b'# H4R12_DEV_'+b'END\n'
    h4m12_req(raw.count(begin)==raw.count(end)==1,'R12_PROJECTION_BLOCK')
    i=raw.index(begin);j=raw.index(end,i)+len(end)
    s=(raw[:i]+raw[j:]).decode('utf8')
    for before,after in reversed(H4R12_DEV_PATCHES):
        h4m12_req(s.count(after)==1,'R12_REVERSE_ANCHOR')
        s=s.replace(after,before,1)
    data=s.encode('utf8')
    h4m12_req(hashlib.sha1(b'blob '+str(len(data)).encode()+b'\0'+data).hexdigest()==H4R12_DEV_BASE_BLOB,
        'R12_HISTORICAL_EVALUATOR')
    return data

def h4r12_dev_project(root):
    import ast
    raw=(root/'m463_gate3_cp_eval.py').read_bytes()
    compile(raw,'<R12 DEV evaluator>','exec')
    prev=h4r12_dev_projection(raw)
    old=subprocess.check_output(['git','show',H4R12_DEV_BASE+':m463_gate3_cp_eval.py'],cwd=root)
    h4m12_req(prev==old,'R12_EXACT_BYTE_PROJECTION')
    a,b=ast.parse(old),ast.parse(raw)
    def top(tree,name):
        return next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name==name)
    def step(tree):
        return next(n for n in ast.walk(top(tree,'run')) if isinstance(n,ast.FunctionDef) and n.name=='one_step')
    h4m12_req(ast.dump(step(a),include_attributes=False)==ast.dump(step(b),include_attributes=False),'R12_STEP_GRAPH')
    for n in ('h3_group','h3_decode','h3_summary','h3_decide','h4_shared_frozen_loader'):
        h4m12_req(ast.dump(top(a,n),include_attributes=False)==ast.dump(top(b,n),include_attributes=False),'R12_UNCHANGED_'+n)

def h4r12_dev_disposition(result):
    scientific=result['decision']
    h4m12_req(scientific in ('NO_GO','INCONCLUSIVE','DEV_PASS')
        and scientific==result['official']['decision'],'R12_SCIENTIFIC_RESULT')
    result.update(scientific_gate_result=scientific,decision='NO_PROMOTE',
                  training_exposure='EXPOSURE_INCONCLUSIVE',holdout_authorized=False)

def h4r12_dev_exposure_contract(r):
    import m463_push_ppo_train as t
    e=r['r12_exposure']
    h4m12_req(r['status']=='TECHNICAL_PASS' and r['promotion_authorized'] is False
        and e==t.h4r12_exposure_replay(r) and e['decision']=='EXPOSURE_INCONCLUSIVE'
        and e['checks']==dict(total=True,first_half=True,second_half=False,left=True,right=True,both=True,nominal=True)
        and e['halves']==[57919,642] and e['totals']['nonzero_consumed']==58561
        and e['nominal']==1143687,'R12_EXPOSURE_LOCK')

def h4r12_dev_training_contract(root,r):
    import m463_push_ppo_train as t
    h4r12_dev_exposure_contract(r)
    h4m12_req(r['authorization']==H4R12_DEV_TRAIN_AUTH
        and r['artifacts'][H4M12_POLICY]==H4R12_DEV_TRAIN_PINS[H4M12_POLICY]
        and r['parent']['matched_control']['ctrl_dev_sha256']==H4CC_ARCHIVE_SHA
        and r['parent']['matched_control']['m12_dev_sha256']==H4RED_EVAL_M12_PINS['report.json'],
        'R12_TRAIN_APPROVAL')
    static=root/H4R12_DEV_TRAIN_AUTH['static_path']
    runtime=root/'m463_runs/m470_h4r12_runtime_v1.log'
    t.h4x_file_pin(static,H4R12_DEV_TRAIN_AUTH['static_sha256'])
    t.h4x_file_pin(runtime,H4R12_DEV_TRAIN_RUNTIME_SHA)
    h4m12_req(max(static.stat().st_size,runtime.stat().st_size)<=16*1024**2,'R12_TRAIN_LOG_CAP')
    lines=static.read_text('utf8').splitlines()
    h4m12_req(lines[-2:]==['H4R12_FULL_STATIC_PASS','STATIC_EXIT_CODE=0 TEE_EXIT_CODE=0'],'R12_TRAIN_STATIC_FOOTER')
    for line in ('H4R12_FULL_STATIC_PASS','H4R12_SOURCE '+H4R12_DEV_TRAIN_AUTH['source_sha256'],
                 'H4R12_GENERATED '+H4R12_DEV_TRAIN_AUTH['generated_sha256']):
        h4m12_req(lines.count(line)==1,'R12_TRAIN_STATIC')
    lines=runtime.read_text('utf8').splitlines()
    h4m12_req(lines[-2:]==['H4R12_TECHNICAL_PASS '+H4R12_DEV_TRAIN_PINS['report.json']+' EXPOSURE_INCONCLUSIVE',
        'H4R12_EXIT_CODE=0 LOG_CAP_EXIT_CODE=0 TEE_EXIT_CODE=0'],'R12_TRAIN_RUNTIME_FOOTER')
    previous=h4r12_dev_projection((root/'m463_gate3_cp_eval.py').read_bytes())
    names=(*t.H4_FILES,'m463_gate3_cp_eval.py','paper_config_preflight.json')
    payload={n:(hashlib.sha256(previous).hexdigest() if n=='m463_gate3_cp_eval.py' else sha256(root/n)) for n in names}
    h4m12_req(h4m3_digest(payload)==H4R12_DEV_TRAIN_AUTH['source_sha256'],'R12_HISTORICAL_TRAIN_SOURCE')

def h4r12_dev_static(root):
    root=Path(root).resolve()
    h4m3_no_runtime_imports()
    path=root/H4R12_DEV_OUTPUT
    log=root/'m463_runs/m470_h4r12_dev_runtime_v1.log'
    h4m12_req(not path.parent.exists() and not path.parent.is_symlink()
        and not log.exists() and not log.is_symlink(),'RED_STATIC_USED')
